WITH calendar AS (SELECT d::DATE AS mon FROM generate_series(DATE '2024-01-01',DATE '2024-12-01',INTERVAL '1 month') t(d)),matrix AS (PIVOT (SELECT date_trunc('month',refunded_at AT TIME ZONE 'UTC')::DATE AS mon,reason,qty::BIGINT AS qty FROM returns WHERE status='refunded' AND refunded_at>=TIMESTAMPTZ '2024-01-01 00:00:00+00' AND refunded_at<TIMESTAMPTZ '2025-01-01 00:00:00+00') ON reason IN ('damaged','wrong_item','unwanted') USING sum(qty) GROUP BY mon) SELECT c.mon,coalesce(m.damaged,0)::BIGINT AS damaged,coalesce(m.wrong_item,0)::BIGINT AS wrong_item,coalesce(m.unwanted,0)::BIGINT AS unwanted FROM calendar c JOIN matrix m USING(mon) ORDER BY c.mon;
